function validate([startWords, targetWords]) {
  for (const [name, words] of [['startWords', startWords], ['targetWords', targetWords]]) {
    if (!Array.isArray(words) || words.length < 1 || words.length > 50000) return `${name} needs 1 to 50000 words.`;
    for (const word of words) {
      if (typeof word !== 'string' || !/^[a-z]{1,26}$/.test(word)) return `Each word in ${name} has 1 to 26 lowercase letters.`;
      if (new Set(word).size !== word.length) return `No word in ${name} may repeat a letter.`;
    }
  }
  return null;
}

