function wordCount(startWords, targetWords) {
  const toMask = (word) => {
    let mask = 0;
    for (const ch of word) {
      mask |= 1 << (ch.charCodeAt(0) - 97);
    }
    return mask;
  };

  const seen = new Set();
  for (const word of startWords) {
    seen.add(toMask(word));
  }

  let count = 0;
  for (const word of targetWords) {
    const mask = toMask(word);
    for (const ch of word) {
      const bit = 1 << (ch.charCodeAt(0) - 97);
      if (seen.has(mask ^ bit)) {
        count++;
        break;
      }
    }
  }
  return count;
}

