function wordCount(startWords, targetWords) {
  let total = 0;
  for (const target of targetWords) {
    // Reachable when some start word is one letter shorter and every one of its letters is in the target.
    const ok = startWords.some(start => start.length + 1 === target.length && [...start].every(c => target.includes(c)));
    if (ok) total++;
  }
  return total;
}

