function generate(rand, size) {
  const large = size === 'large';
  const alphabet = large ? 26 : 3 + Math.floor(rand() * 4);
  const pickInt = (k) => Math.floor(rand() * k);
  const shuffle = (letters) => {
    for (let i = letters.length - 1; i > 0; i--) {
      const j = pickInt(i + 1);
      [letters[i], letters[j]] = [letters[j], letters[i]];
    }
    return letters;
  };
  const letters = (k) => Array.from({ length: k }, (_, i) => String.fromCharCode(97 + i));
  const randomWord = () => shuffle(letters(alphabet)).slice(0, 1 + pickInt(large ? alphabet : Math.min(alphabet, 4))).join('');
  const startWords = Array.from({ length: large ? 2000 : 1 + pickInt(6) }, randomWord);
  const targetCount = large ? 2000 : 1 + pickInt(6);
  const targetWords = [];
  for (let i = 0; i < targetCount; i++) {
    const base = startWords[pickInt(startWords.length)];
    const missing = letters(Math.min(26, alphabet + 1)).filter(ch => !base.includes(ch));
    const mode = rand();
    // Mix reachable targets (a start word plus a new letter) with near misses and unrelated words.
    if (mode < 0.5 && missing.length > 0) targetWords.push(shuffle([...base, missing[pickInt(missing.length)]]).join(''));
    else if (mode < 0.65) targetWords.push(shuffle([...base]).join(''));
    else if (mode < 0.75 && base.length > 1) targetWords.push(shuffle([...base].slice(1)).join(''));
    else targetWords.push(randomWord());
  }
  return [startWords, targetWords];
}
